import source from "../data/customerSegmentation2026.json";
import { CUSTOMER_GROUPS, type CustomerGroupCode } from "../domain/fieldSales";

type Row = Record<string, unknown> & { id: string | number };
type Section = keyof typeof source.sheets;
type SourceRow = (typeof source.sheets)[Section]["records"][number];
type Evidence = ReturnType<typeof evidence>;

export const customerSegmentationVersion = `customer-segmentation-2026:${source.sha256}`;

const text = (value: unknown): string =>
  typeof value === "string" ? value.trim() : "";
const nameKey = (name: unknown) =>
  text(name)
    .normalize("NFKC")
    .toLowerCase()
    .replace(/[^\p{L}\p{N}\p{M}]/gu, "");
const codes = (value: unknown) =>
  text(value)
    .toUpperCase()
    .split(/\s*,\s*/)
    .filter(Boolean);
const object = (value: unknown): Record<string, unknown> =>
  value && typeof value === "object" && !Array.isArray(value)
    ? (value as Record<string, unknown>)
    : {};
const missing = (value: unknown) =>
  value == null ||
  (["", "-", "unknown", "n/a"].includes(text(value).toLowerCase()) &&
    typeof value === "string");
const isPlaceholder = (name: unknown) =>
  /^(?:ERP_Code_|รหัส ERP )/i.test(text(name));

function evidence(section: Section, { row, cells }: SourceRow) {
  const { sheet, headers } = source.sheets[section];
  return {
    file: source.file,
    sheet,
    row,
    sha256: source.sha256,
    values: Object.fromEntries(
      headers.map((header, index) => [header, cells[index]]),
    ),
  };
}

/** Import workbook-backed fields without changing existing CRM IDs or manual values. */
export function importCustomerSegmentation(
  companies: Row[],
  masterOptions: Row[],
): Row[] {
  const directory = companies.map((company) => ({ ...company }));
  const groups = new Map(
    masterOptions
      .filter((option) => option.category === "customer_group")
      .map((option) => [option.code, option.id]),
  );
  const groupCode = (value: unknown): CustomerGroupCode | undefined =>
    CUSTOMER_GROUPS.find(
      (group) => text(value) === `${group.order}. ${group.labelTh}`,
    )?.code;
  const groupId = (value: unknown) => groups.get(groupCode(value));
  let nextId =
    directory.reduce(
      (max, company) => Math.max(max, Number(company.id) || 0),
      20000,
    ) + 1;

  const byCode = (code: string) =>
    directory.filter((company) => {
      const fields = object(company.custom_fields);
      const imported = object(fields.customer_segmentation_2026);
      return [
        ...codes(company.customer_code),
        ...codes(fields.erp_customer_code),
        ...(Array.isArray(imported.erp_codes) ? imported.erp_codes : []),
      ].includes(code);
    });

  const byName = (name: unknown) => {
    const key = nameKey(name);
    return key
      ? directory.filter((company) => nameKey(company.name) === key)
      : [];
  };
  const unique = (rows: Row[]) => (rows.length === 1 ? rows[0] : undefined);

  function enrich(
    company: Row,
    details: Evidence,
    options: {
      erpCodes?: string[];
      name?: string;
      aliases?: string[];
      group?: Row["id"];
      province?: string;
    },
  ) {
    const fields = object(company.custom_fields);
    const existing = object(fields.customer_segmentation_2026);
    const sourceRows = Array.isArray(existing.source_rows)
      ? existing.source_rows.filter(
          (value) => value.sheet !== details.sheet || value.row !== details.row,
        )
      : [];
    const erpCodes = [
      ...new Set([
        ...(Array.isArray(existing.erp_codes) ? existing.erp_codes : []),
        ...(options.erpCodes ?? []),
      ]),
    ];
    const aliases = [
      ...new Set(
        [
          ...(Array.isArray(existing.names) ? existing.names : []),
          options.name,
          ...(options.aliases ?? []),
        ].filter(Boolean),
      ),
    ];
    company.custom_fields = {
      ...fields,
      customer_segmentation_2026: {
        ...existing,
        erp_codes: erpCodes,
        names: aliases,
        source_rows: [...sourceRows, details],
      },
    };
    if (
      options.name &&
      (missing(company.name) || isPlaceholder(company.name))
    ) {
      company.name = options.name;
      if (company.province === "Unknown" && !options.province)
        company.province = null;
    }
    if (missing(company.customer_code) && erpCodes.length)
      company.customer_code = erpCodes[0];
    if (missing(company.customer_group_id) && options.group != null)
      company.customer_group_id = options.group;
    if (missing(company.province) && options.province)
      company.province = options.province;
  }

  function add(name: string, code?: string) {
    const company: Row = {
      id: nextId++,
      name,
      customer_code: code ?? null,
      sales_id: null,
      nb_contacts: 0,
      nb_deals: 0,
    };
    directory.push(company);
    return company;
  }

  for (const record of source.sheets.active.records) {
    const [, codeCell, nameCell, segment, forecastCell, , , , , provinceCell] =
      record.cells;
    const erpCodes = codes(codeCell);
    const name = text(nameCell);
    const forecast = text(forecastCell);
    const details = evidence("active", record);
    const options = {
      name,
      aliases:
        forecast && forecast !== "-" && !forecast.startsWith("(")
          ? [forecast]
          : [],
      group: groupId(segment),
      province: missing(provinceCell)
        ? undefined
        : text(provinceCell).replace(/^จังหวัด\s*/, ""),
    };
    const forecastCompany = options.aliases.length
      ? unique(byName(forecast))
      : undefined;
    const exact = erpCodes.map((code) => ({ code, matches: byCode(code) }));
    const matched = [...new Set(exact.flatMap(({ matches }) => matches))];
    // Match by name only when the row has no other ERP code. A forecast name
    // may classify its survey row, but must not collapse distinct CRM IDs.
    const nameCandidate = unique(byName(name)) ?? forecastCompany;
    const canUseName =
      nameCandidate &&
      ![
        nameCandidate.customer_code,
        object(nameCandidate.custom_fields).erp_customer_code,
      ].some((value) => text(value) && !text(value).startsWith("CL-"));
    const unassigned = exact
      .filter(({ matches }) => !matches.length)
      .map(({ code }) => code);
    if (unassigned.length) {
      const company =
        matched.length === 1
          ? matched[0]
          : canUseName && !matched.length
            ? nameCandidate
            : add(name, unassigned[0]);
      enrich(company, details, { ...options, erpCodes: unassigned });
    }
    for (const company of matched) {
      enrich(company, details, {
        ...options,
        erpCodes: exact
          .filter(({ matches }) => matches.includes(company))
          .map(({ code }) => code),
      });
    }
    if (forecastCompany && !matched.includes(forecastCompany)) {
      enrich(forecastCompany, details, { group: options.group });
    }
  }

  for (const record of source.sheets.openOrders.records) {
    const [, codeCell, nameCell, matchStatus, segment] = record.cells;
    const [code] = codes(codeCell);
    const name = text(matchStatus).startsWith("Unmatched")
      ? undefined
      : text(nameCell).replace(/\s*\(Forecast Nov\/07\)$/, "");
    const matches = byCode(code);
    const forecastCompany =
      name && text(matchStatus).startsWith("Matched via Forecast")
        ? unique(byName(name))
        : undefined;
    const details = evidence("openOrders", record);
    const targets = matches.length
      ? matches
      : [forecastCompany ?? add(name || `รหัส ERP ${code} · รอตรวจสอบ`, code)];
    for (const company of targets) {
      enrich(company, details, {
        name,
        group: groupId(segment),
        erpCodes: [code],
      });
    }
    if (forecastCompany && !targets.includes(forecastCompany)) {
      enrich(forecastCompany, details, { group: groupId(segment) });
    }
  }

  for (const record of source.sheets.inactive.records) {
    const [, nameCell, segment] = record.cells;
    const name = text(nameCell);
    const matches = byName(name);
    for (const company of matches.length ? matches : [add(name)]) {
      enrich(company, evidence("inactive", record), {
        name,
        group: groupId(segment),
      });
    }
  }
  for (const company of directory) {
    const surveyType = object(
      object(company.custom_fields).agriculture_survey,
    ).CustomerType;
    if (surveyType === "Sugar Mill" && missing(company.customer_group_id)) {
      const group = groups.get("sugar_mill");
      if (group != null) company.customer_group_id = group;
    }
  }
  return directory;
}
