import source from "../data/customerList.json";
import referenceData from "./referenceData.json";
import { DEMO_ACCOUNTS, type DdcDemoDb } from "./generateDemoData";
import { RESOURCE_DEFS } from "../resources/registry";

/** Local source-backed workspace. Operational demo records are never mixed in. */
export const generateCustomerListData = (): DdcDemoDb => {
  const db: Record<string, unknown[]> = {};
  for (const def of RESOURCE_DEFS) db[def.name] = [];
  for (const name of [
    "contacts",
    "contact_notes",
    "deals",
    "deal_notes",
    "tasks",
    "tags",
    "notifications",
    "audit_log",
    "erp_external_ids",
    "erp_sync_cursors",
    "erp_connector_config",
    "configuration",
  ])
    db[name] = [];
  for (const [table, rows] of Object.entries(referenceData))
    db[table] = structuredClone(rows);
  for (const [table, rows] of Object.entries(source.tables))
    db[table] = structuredClone(rows);
  db.sales = DEMO_ACCOUNTS.map((account) => ({
    ...account,
    disabled: false,
    user_id: String(account.id),
    password: "demo",
  }));
  db.configuration = [{ id: 1, config: {} }];
  return db as DdcDemoDb;
};
