import type { AuthProvider } from "ra-core";

import type { Sale } from "../../types";
import { dataProvider as defaultDataProvider } from "./dataProvider";
import type { CrmDataProvider } from "../types";
import { canAccessResource } from "@/ddc/domain/permissions";
import { canAccess as atomicCanAccess } from "../commons/canAccess";

export const DEFAULT_USER = {
  id: 0,
  first_name: "Jane",
  last_name: "Doe",
  email: "janedoe@atomic.dev",
  password: "demo",
  administrator: true,
  avatar: {
    src: "data:image/jpeg;base64,",
  },
} as const;

export const USER_STORAGE_KEY = "user";

localStorage.setItem(USER_STORAGE_KEY, JSON.stringify({ ...DEFAULT_USER }));

async function getUser(dataProvider: CrmDataProvider, email: string) {
  const sales = await dataProvider.getList("sales", {
    pagination: { page: 1, perPage: 200 },
    sort: { field: "name", order: "ASC" },
  });

  if (!sales.data.length) {
    return { ...DEFAULT_USER };
  }

  const user = sales.data.find((sale) => sale.email === email);
  if (!user || user.disabled) {
    if (sales.data.some((sale) => sale.role_key)) {
      // DDC evaluation data: only the listed demo accounts may sign in
      throw new Error("Unknown or disabled demo account");
    }
    return { ...DEFAULT_USER };
  }
  return user;
}

/** Builds the evaluation mode auth provider on top of a FakeRest data provider. */
export const createAuthProvider = (
  dataProvider: CrmDataProvider,
): AuthProvider => ({
  login: async ({ email }) => {
    const user = await getUser(dataProvider, email);
    localStorage.setItem(USER_STORAGE_KEY, JSON.stringify(user));
    return Promise.resolve();
  },
  resetPassword: async () => {
    // FakeRest doesn't send real emails. Keep this async to mimic network latency.
    await new Promise((resolve) => setTimeout(resolve, 250));
    return;
  },
  setPassword: async () => {
    // FakeRest doesn't persist auth credentials. This is only for local UX testing.
    await new Promise((resolve) => setTimeout(resolve, 250));
    return;
  },
  logout: () => {
    localStorage.removeItem(USER_STORAGE_KEY);
    return Promise.resolve();
  },
  checkError: () => Promise.resolve(),
  checkAuth: () =>
    localStorage.getItem(USER_STORAGE_KEY)
      ? Promise.resolve()
      : Promise.reject(),
  canAccess: async ({ signal: _signal, ...params }) => {
    // Get the current user
    const userItem = localStorage.getItem(USER_STORAGE_KEY);
    const localUser = userItem ? (JSON.parse(userItem) as Sale) : null;
    if (!localUser) return false;

    // Rights come from the DDC permission matrix of the user role
    const access = await dataProvider.getMyAccess();
    if (!access.administrator && access.roleKey == null) {
      // Datasets without DDC roles (stock Atomic CRM data and its tests) keep the Atomic CRM rules
      return atomicCanAccess("user", params);
    }
    return canAccessResource(access, params);
  },
  getIdentity: () => {
    const userItem = localStorage.getItem(USER_STORAGE_KEY);
    const user = userItem ? (JSON.parse(userItem) as Sale) : null;
    return Promise.resolve({
      id: user?.id ?? 0,
      fullName: user ? `${user.first_name} ${user.last_name}` : "Jane Doe",
      avatar: user?.avatar?.src,
    });
  },
  async getAuthorizationDetails() {
    await new Promise((resolve) => setTimeout(resolve, 500));
    // return dummy data to avoid errors in OAuthConsentPage
    return {
      data: {
        authorization_id: "dummy",
        user: {
          id: "0",
          email: "johndoe@example.com",
        },
        client: {
          name: "Dummy Client",
        },
        scope: "openid profile email phone",
        redirect_uri: "https://example.com/auth_callback",
      },
      error: null,
    };
  },
  async approveAuthorization() {
    // return dummy success response
    return {
      data: {
        redirect_url: "https://example.com/auth_callback",
      },
      error: null,
    };
  },
  async denyAuthorization() {
    // return dummy denied response
    return {
      data: {
        redirect_url: "https://example.com/denied",
      },
      error: null,
    };
  },
});

// Resolved at call time: dataProvider.ts imports this module (circular import)
export const authProvider: AuthProvider = createAuthProvider(
  new Proxy({} as CrmDataProvider, {
    get: (_target, key) => (defaultDataProvider as any)[key],
  }),
);
