import { memoryStore } from "ra-core";
import { CRM } from "@/components/atomic-crm/root/CRM";
import { createLanAuth } from "@/ddc/providers/lanAuth";
import { ddcConfiguration } from "@/ddc/config";
import { generateAgricultureData } from "@/ddc/demo/agricultureData";
import { agriculture } from "@/ddc/agriculture/data";
import { openLocalWorkspace } from "@/ddc/providers/localWorkspace";
import { machineModelAddition } from "@/ddc/demo/machineModelData";
import {
  customerSegmentationVersion,
  importCustomerSegmentation,
} from "@/ddc/demo/customerSegmentationData";

/**
 * Local Agriculture workspace: source evidence seeds the first launch.
 * All subsequent mutations persist in IndexedDB on this browser and origin.
 * LAN accounts authenticate against the host; demo CRM records remain browser-local.
 */
const { authProvider, getUser } = createLanAuth();
const startup = await openLocalWorkspace(
  generateAgricultureData(),
  agriculture.source_version,
  undefined,
  machineModelAddition(),
  { authProvider, getCurrentUser: getUser },
  { version: customerSegmentationVersion, apply: importCustomerSegmentation },
)
  .then((provider) => ({ provider, error: null }))
  .catch((error: unknown) => ({
    provider: null,
    error: error instanceof Error ? error.message : String(error),
  }));
const App = () =>
  startup.provider ? (
    <CRM
      {...ddcConfiguration}
      dataProvider={startup.provider}
      authProvider={authProvider}
      store={memoryStore()}
    />
  ) : (
    <main className="mx-auto max-w-2xl p-8" role="alert">
      <h1 className="text-xl font-semibold">
        Local CRM storage needs attention
      </h1>
      <p className="mt-4">{startup.error}</p>
      <p className="mt-4">
        Existing saved data has not been deleted. Keep this browser profile and
        use the same CRM address.
      </p>
    </main>
  );

export default App;
