import {
  defaultCompanySectors,
  defaultCurrency,
  defaultDarkModeLogo,
  defaultDealCategories,
  defaultDealPipelineStatuses,
  defaultDealStages,
  defaultLightModeLogo,
  defaultNoteStatuses,
  defaultTaskTypes,
  defaultTitle,
} from "./defaultConfiguration";
import { ddcI18nProvider as defaulti18nProvider } from "@/ddc/i18n/i18nProvider";
import { StartPage } from "../login/StartPage.tsx";
import { DdcLayout } from "@/ddc/layout/DdcLayout";
import { DdcDashboard } from "@/ddc/features/DdcDashboard";
import { FieldVisitPage } from "@/ddc/features/field/FieldVisitPage";
import { VisitTimelinePage } from "@/ddc/features/field/VisitTimelinePage";
import { PartCatalogPage } from "@/ddc/features/field/PartCatalogPage";
import { WorkspacePageView } from "@/ddc/pages/WorkspacePageView";
import { ActivityCalendar } from "@/ddc/features/ActivityCalendar";
import { ErpAdminPage } from "@/ddc/features/ErpAdminPage";
import { ERP_ENABLED } from "@/ddc/featureFlags";
import { PermissionsPage } from "@/ddc/features/PermissionsPage";
