import raw from "../data/agriculture2027.json";

export type EvidenceRow = Record<string, string | number | null>;
export type Scenario = "60M" | "80M" | "100M";
export interface SourceFile {
  relative: string;
  source_path: string;
  bytes: number;
  sha256: string;
  url: string;
}
interface AgriculturePackage {
  source_version: string;
  source_root: string;
  as_of: string;
  source_files: SourceFile[];
  tables: Record<string, Array<Record<string, unknown> & { id: number }>>;
  scenarios: Record<Scenario, EvidenceRow[]>;
  actual: EvidenceRow[];
  orders: EvidenceRow[];
  pipeline: EvidenceRow[];
  customers: EvidenceRow[];
  opportunities: EvidenceRow[];
  customer_plan: EvidenceRow[];
  actions: EvidenceRow[];
  risks: EvidenceRow[];
  gates: EvidenceRow[];
  kpi_rows: Array<{
    values: unknown[];
    source_sheet: string;
    source_row: number;
  }>;
  gantt: Array<{ values: unknown[]; source_sheet: string; source_row: number }>;
  monthly_2026: EvidenceRow[];
  monthly_forecast: EvidenceRow[];
  product_analysis: EvidenceRow[];
  product_groups: EvidenceRow[];
  customer_product_matrix: EvidenceRow[];
  forecast_groups: EvidenceRow[];
  backtests: EvidenceRow[];
  financials: EvidenceRow[];
  growth_bridge: EvidenceRow[];
  target_gaps: EvidenceRow[];
  decision_matrix: EvidenceRow[];
  marketing: EvidenceRow[];
  assumptions: EvidenceRow[];
  gaps: EvidenceRow[];
  source_register: EvidenceRow[];
  quality_issues: EvidenceRow[];
  import_issues: EvidenceRow[];
  account_matches: EvidenceRow[];
  forecast: Record<string, unknown>;
  summary: Record<string, unknown>;
  validation: {
    companies: number;
    survey_accounts: number;
    sku: number;
    actual_lines: number;
    open_so_lines: number;
    actual_revenue: number;
    actual_quantity: number;
    scenario_totals: Record<Scenario, number>;
    new_erp_accounts: number;
    matched_erp_to_survey: number;
    packing_checks: number;
    packing_failures: number;
  };
}
export const agriculture = raw as unknown as AgriculturePackage;
export const amount = (value: unknown): number => Number(value || 0);
export const sumRows = (rows: EvidenceRow[], key: string): number =>
  rows.reduce((total, row) => total + amount(row[key]), 0);
export const sourceUrl = (file: unknown): string | undefined =>
  agriculture.source_files.find((source) => source.relative === file)?.url;
export const companyUrl = (id: unknown) => `/companies/${String(id)}/show`;
export const productUrl = (id: unknown) => `/products/${String(id)}/show`;
