import { agriculture } from "../agriculture/data";
import { generateCustomerListData } from "./customerListData";
import type { DdcDemoDb } from "./generateDemoData";
import { machineModelAddition } from "./machineModelData";

/** Import source evidence without inventing executable deals or sales orders. */
export function generateAgricultureData(): DdcDemoDb {
  const db = generateCustomerListData();
  for (const [table, rows] of Object.entries(agriculture.tables))
    db[table] = structuredClone(rows);
  const actions = agriculture.actions.map((row, index) => ({
    id: 30001 + index,
    description: `[AG27-A${row.rank}] ${row.action}\nProposed owner role: ${row.owner_role}\nTiming: ${row.timing}\nKPI: ${row.kpi}\nDependency: ${row.dependency}\nSource: ${row.source_file} / ${row.source_sheet} / row ${row.source_row}. Proposed plan; approval and actual assignee pending.`,
    status: "open",
    sales_id: null,
    company_id: null,
    due_date: null,
    completed_at: null,
  }));
  const customerActions = agriculture.customer_plan.map((row, index) => ({
    id: 30101 + index,
    company_id: row.company_id ?? null,
    description: `[AG27-C${row.Priority_Rank}] ${row.Customer_Account}\n${row.KPI}\nProposed owner role: ${row.Owner}\nTiming: ${row.Due_Date}\nBudget target (not confirmed sales): ${row.Target_2027_60M_THB} THB\nIdentity: ${row.link_status}\nSource: ${row.source_file} row ${row.source_row}. Assignee and exact due date pending.`,
    status: "open",
    sales_id: null,
    due_date: null,
    completed_at: null,
  }));
  const gapActions = agriculture.gaps.map((row, index) => ({
    id: 30201 + index,
    description: `[${row["Gap ID"]}] ${row["Missing / Incomplete Data"]}\nAction: ${row["Action to Close Gap"]}\nProposed owner role: ${row.Owner}\nTiming: ${row["Target Close"]}\nSource: ${row.source_file} row ${row.source_row}. Assignment pending.`,
    status: "open",
    sales_id: null,
    company_id: null,
    due_date: null,
    completed_at: null,
  }));
  db.action_items = [...actions, ...customerActions, ...gapActions];
  const origin = globalThis.location?.origin ?? "http://127.0.0.1:5180";
  const documents: Array<Record<string, unknown> & { id: number }> = [];
  const attach = (
    entity: string,
    id: number,
    title: string,
    file: string,
    row: unknown,
  ) => {
    const source = agriculture.source_files.find(
      (item) => item.relative === file,
    );
    if (!source) throw new Error(`Missing source snapshot: ${file}`);
    documents.push({
      id: 50001 + documents.length,
      entity_type: entity,
      entity_id: id,
      document_type_id: null,
      title,
      reference_no: `AG27 / row ${String(row)}`,
      revision: "Source snapshot 2026-11-26",
      external_url: `${origin}${source.url}`,
      notes: `Source: ${source.source_path}\nRecord row: ${String(row)}\nSHA-256: ${source.sha256}\nSource evidence only; approval, identity matching, dimensions and fitment require confirmation.`,
      sales_id: null,
      created_at: "2026-11-26T00:00:00.000Z",
    });
  };
  for (const row of agriculture.pipeline)
    attach(
      "companies",
      Number(row.company_id),
      "Agriculture 2027 · Field survey evidence",
      String(row.source_file),
      row.source_row,
    );
  for (const row of agriculture.customers)
    attach(
      "companies",
      Number(row.company_id),
      `Agriculture 2027 · ERP performance · ${row.CustomerCode}`,
      String(row.source_file),
      row.source_row,
    );
  for (const product of agriculture.tables.products) {
    const master = (
      product.custom_fields as { agriculture_master: Record<string, unknown> }
    ).agriculture_master;
    attach(
      "products",
      product.id,
      `Agriculture 2027 · SKU source · ${product.part_number}`,
      String(master.source_file),
      master.source_row,
    );
  }
  for (const [scenario, rows] of Object.entries(agriculture.scenarios)) {
    for (const row of rows) {
      if (row.product_id == null) continue;
      attach(
        "products",
        Number(row.product_id),
        `Agriculture 2027 · ${scenario} budget proposal (not actual sales)`,
        String(row.source_file),
        row.source_row,
      );
      documents[documents.length - 1].notes +=
        `\nProposed annual quantity: ${row.Total_Annual_Qty} ${row.Sales_Unit}\nProposed annual revenue: ${row.Total_Annual_Rev} THB Ex-VAT\nBudget unit price: ${row.Unit_Price_ExVAT} THB\nEvidence basis: ${row.Evidence_Basis}\nThese are scenario assumptions and require commercial approval.`;
    }
  }
  for (const row of agriculture.customer_plan) {
    if (row.company_id == null) continue;
    attach(
      "companies",
      Number(row.company_id),
      "Agriculture 2027 · Account budget and execution proposal",
      String(row.source_file),
      row.source_row,
    );
    documents[documents.length - 1].notes +=
      `\nProposed target: ${row.Target_2027_60M_THB} THB\nProducts: ${row.Target_Product}\nKPI: ${row.KPI}\nOwner role (assignment pending): ${row.Owner}\nTiming: ${row.Due_Date}\nThis is a planning target, not an awarded opportunity or customer purchase order.`;
  }
  db.document_references = documents;
  for (const [table, rows] of Object.entries(machineModelAddition().tables))
    db[table] = [...(db[table] ?? []), ...structuredClone(rows)];
  return db;
}
