import raw from "../data/machineModels.json";
import type { SeedAddition } from "../providers/localWorkspace";

export const machineModelSummary = raw.summary;

/** Keep model-source additions separate from the sales baseline fingerprint. */
export function machineModelAddition(): SeedAddition {
  const origin = globalThis.location?.origin ?? "http://127.0.0.1:5180";
  return {
    version: raw.version,
    tables: {
      manufacturers: structuredClone(raw.tables.manufacturers),
      machine_models: structuredClone(raw.tables.machine_models),
      document_references: raw.tables.document_references.map((document) => ({
        ...document,
        external_url: `${origin}${document.external_url}`,
      })),
    },
  };
}
